import { debug, setFailed, setOutput } from '@actions/core';
import { startTunnel } from '@stablyhq/runner-sdk';
import { fetchMetadata } from './github/fetch-metadata';
import {
  upsertGitHubComment,
  upsertGitHubCommentV2
} from './github/github_comment';
import { type ParsedInput, parseInput } from './input';
import {
  startTestSuite,
  waitForTestSuiteRunResult
} from './stably/api/agent-api';
import {
  startPlaywrightRun,
  waitForPlaywrightRunResult
} from './stably/api/playwright-api';
import { getSuiteRunDashboardUrl } from './stably/url';

type V1Input = Extract<ParsedInput, { version: 'v1' }>;
type V2Input = Extract<ParsedInput, { version: 'v2' }>;

/**
 * The main function for the action.
 * @returns {Promise<void>} Resolves when the action is complete.
 */
export async function run(): Promise<void> {
  try {
    const input = parseInput();
    const { version } = input;

    await (version === 'v1' ? runV1(input) : runV2(input));
  } catch (error) {
    // Fail the workflow run if an error occurs
    if (error instanceof Error) setFailed(error.message);
  } finally {
    // Make sure the process exits
    // This is done to prevent the tunnel from hanging the thread
    process.exit();
  }
}

async function runV1({
  apiKey,
  urlReplacement,
  githubComment,
  githubToken,
  testSuiteId,
  runInAsyncMode,
  environment,
  variableOverrides,
  note
}: V1Input): Promise<void> {
  const shouldTunnel =
    urlReplacement &&
    new URL(urlReplacement.replacement).hostname === 'localhost';

  if (urlReplacement && shouldTunnel) {
    const tunnel = await startTunnel(urlReplacement.replacement);
    urlReplacement.replacement = tunnel.url;
  }

  const githubMetadata = githubToken
    ? await fetchMetadata(githubToken)
    : undefined;
  const { testSuiteRunId } = await startTestSuite({
    testSuiteId,
    apiKey,
    options: {
      urlReplacement,
      environment,
      variableOverrides,
      note
    },
    githubMetadata
  });
  setOutput('testSuiteRunId', testSuiteRunId);

  if (runInAsyncMode) {
    return;
  }

  try {
    const runResult = await waitForTestSuiteRunResult({
      testSuiteRunId,
      apiKey
    });
    const numFailedTests = runResult.results.filter(
      ({ status }) => status === 'FAILED'
    ).length;
    setOutput('success', numFailedTests === 0);
    if (numFailedTests > 0) {
      const suiteRunDashboardUrl = getSuiteRunDashboardUrl({
        projectId: runResult.projectId,
        testSuiteRunId
      });

      setFailed(
        `Test suite run failed (${numFailedTests}/${runResult.results.length} tests). [Dashboard](${suiteRunDashboardUrl})`
      );
    }

    // Github Comment Code
    if (githubComment && githubToken) {
      await upsertGitHubComment(testSuiteId, githubToken, {
        result: runResult
      });
    }
  } catch (e) {
    debug(`API call error: ${e}`);
    setFailed(e instanceof Error ? e.message : `An unknown error occurred`);
  }
}

async function runV2({
  apiKey,
  projectId,
  playwrightProjectName,
  githubComment,
  githubToken,
  runInAsyncMode,
  envOverrides,
  environmentName
}: V2Input): Promise<void> {
  const { runId } = await startPlaywrightRun({
    projectId,
    apiKey,
    options: {
      playwrightProjectName,
      envOverrides,
      environmentName
    }
  });
  setOutput('testSuiteRunId', runId);

  if (runInAsyncMode) {
    return;
  }

  try {
    const runResult = await waitForPlaywrightRunResult({
      projectId,
      runId,
      apiKey
    });

    const numFailedTests =
      runResult.results?.testCases.filter(({ status }) => status === 'FAILED')
        .length ?? 0;
    const totalTests = runResult.results?.testCases.length ?? 0;

    setOutput('success', numFailedTests === 0 && runResult.status === 'PASSED');

    if (numFailedTests > 0 || runResult.status !== 'PASSED') {
      setFailed(
        `Playwright test run failed (${numFailedTests}/${totalTests} tests failed, status: ${runResult.status}). [Dashboard](https://app.stably.ai/project/${projectId}/playwright/history/${runId}?tab=specs)`
      );
    }

    // Github Comment Code
    if (githubComment && githubToken) {
      await upsertGitHubCommentV2(
        projectId,
        runId,
        githubToken,
        {
          result: runResult
        },
        playwrightProjectName
      );
    }
  } catch (e) {
    debug(`API call error: ${e}`);
    setFailed(e instanceof Error ? e.message : `An unknown error occurred`);
  }
}

/**
 * The entrypoint for the action.
 */
import { run } from './main';

run();

import { getInput, type InputOptions, setFailed } from '@actions/core';
import { load } from 'js-yaml';

const NEWLINE_REGEX = /\r|\n/;
const TRUE_VALUES = new Set(['true', 'yes', '1']);

function getBoolInput(name: string, options?: InputOptions) {
  return TRUE_VALUES.has(getInput(name, options).toLowerCase().trim());
}

function getList(name: string, options?: InputOptions) {
  return getInput(name, options).split(NEWLINE_REGEX).filter(Boolean);
}

type BaseInput = {
  apiKey: string;
  githubToken: string | undefined;
  githubComment: boolean;
  runInAsyncMode: boolean;
};

type V2Input = BaseInput & {
  version: 'v2';
  projectId: string;
  playwrightProjectName: string | undefined;
  envOverrides: Record<string, string> | undefined;
  environmentName: string | undefined;
};

type V1Input = BaseInput & {
  version: 'v1';
  testSuiteId: string;
  urlReplacement:
    | {
        original: string;
        replacement: string;
      }
    | undefined;
  environment: string;
  variableOverrides: Record<
    string,
    string | { value: string | object; sensitive?: boolean }
  >;
  note: string;
};

export type ParsedInput = V1Input | V2Input;

export function parseInput(): ParsedInput {
  const apiKey = getInput('api-key', { required: true });

  // V2 inputs
  const projectId = getInput('project-id');
  // playwright-project-name is the new preferred input, run-group-name is deprecated
  const playwrightProjectNameInput = getInput('playwright-project-name').trim();
  const runGroupNameInput = getInput('run-group-name').trim();
  const playwrightProjectName = playwrightProjectNameInput || runGroupNameInput;
  const envOverridesJson = getInput('env-overrides');
  const envOverrides = envOverridesJson
    ? (parseObjectInput('env-overrides', envOverridesJson) as Record<
        string,
        string
      >)
    : undefined;
  const environmentName = getInput('environment-name').trim() || undefined;

  // V1 inputs (supporting deprecating of runGroupIds)
  const testSuiteIdInput = getInput('test-suite-id');
  const testGroupIdInput = getInput('test-group-id');
  const testSuiteId = testSuiteIdInput || testGroupIdInput;

  // Validation: require either projectId (v2) OR testSuiteId (v1), but not both
  if (projectId && testSuiteId) {
    setFailed(
      'Cannot use both project-id (v2) and test-suite-id (v1). Please use one or the other.'
    );
    throw Error(
      'Cannot use both project-id (v2) and test-suite-id (v1). Please use one or the other.'
    );
  }

  if (!projectId && !testSuiteId) {
    setFailed(
      'Either project-id (v2) or test-suite-id (v1) is required. Please provide one.'
    );
    throw Error(
      'Either project-id (v2) or test-suite-id (v1) is required. Please provide one.'
    );
  }

  // @deprecated
  const deprecatedRawUrlReplacementInput = getList('domain-override');
  const newRawUrlReplacementInput = getList('url-replacement');
  const rawUrlReplacementInput =
    newRawUrlReplacementInput.length > 0
      ? newRawUrlReplacementInput
      : deprecatedRawUrlReplacementInput;
  if (
    rawUrlReplacementInput.length > 0 &&
    rawUrlReplacementInput.length !== 2
  ) {
    setFailed(
      `URL replacment can only be given as a single pair. Given: ${JSON.stringify(
        rawUrlReplacementInput
      )}`
    );
  }
  const [urlReplacementOriginal, urlReplacementNew] = rawUrlReplacementInput;
  const urlReplacement =
    rawUrlReplacementInput.length === 2
      ? {
          original: urlReplacementOriginal,
          replacement: urlReplacementNew
        }
      : undefined;

  const githubToken = getInput('github-token');
  const githubComment = getBoolInput('github-comment');

  const runInAsyncMode = getBoolInput('async');
  const environment = getInput('environment');
  const variableOverridesJson = getInput('variable-overrides');
  const variableOverrides = variableOverridesJson
    ? (parseObjectInput('variable-overrides', variableOverridesJson) as Record<
        string,
        string | { value: string | object; sensitive?: boolean }
      >)
    : {};

  const note = getInput('note');

  return {
    apiKey,
    githubToken: githubToken || process.env.GITHUB_TOKEN,
    githubComment,
    runInAsyncMode,
    ...(projectId
      ? {
          version: 'v2' as const,
          projectId,
          playwrightProjectName: playwrightProjectName || undefined,
          envOverrides,
          environmentName
        }
      : {
          version: 'v1' as const,
          testSuiteId,
          urlReplacement,
          environment,
          variableOverrides,
          note
        })
  } as const;
}

// This method also works with JSON as JSON is is valid YAML
function parseObjectInput(fieldName: string, yaml: string) {
  try {
    const result = load(yaml);
    if (
      typeof result !== 'object' ||
      result === null ||
      Array.isArray(result)
    ) {
      throw new Error(
        `Expected a key-value object, but got ${
          Array.isArray(result) ? 'array' : typeof result
        }`
      );
    }
    return result;
  } catch (e) {
    setFailed(`${fieldName} contains an invalid object: ${e}`);
    throw e;
  }
}

import { warning } from '@actions/core';
import { context, getOctokit } from '@actions/github';
import dedent from 'ts-dedent';
import type { ResultResponse } from '../stably/api/agent-api';
import type { PlaywrightResultResponse } from '../stably/api/playwright-api';
import { getSuiteRunDashboardUrl } from '../stably/url';

const isPermissionError = (error: unknown): boolean => {
  if (error instanceof Error) {
    const message = error.message.toLowerCase();
    return (
      message.includes('resource not accessible by integration') ||
      message.includes('permission') ||
      message.includes('403')
    );
  }
  return false;
};

const handleCommentError = (error: unknown, action: string): void => {
  if (isPermissionError(error)) {
    warning(
      `Skipping GitHub comment (${action}): insufficient permissions. ` +
        `To enable comments, add 'contents: write' and 'pull-requests: write' to your workflow permissions. ` +
        `See: https://docs.github.com/en/actions/using-jobs/assigning-permissions-to-jobs`
    );
  } else {
    throw error;
  }
};

export async function upsertGitHubComment(
  testSuiteId: string,
  githubToken: string,
  resp: { result?: ResultResponse; error?: boolean }
) {
  const octokit = getOctokit(githubToken);

  const projectId = resp.result?.projectId || '';
  const testSuiteRunId = resp.result?.testSuiteRunId || '';
  const testSuiteName = resp.result?.testSuiteName || '';
  const results = resp.result?.results || [];
  const failedTests = results.filter(x => x.status === 'FAILED');
  const successTests = results.filter(
    x => x.status === 'PASSED' || x.status === 'FLAKY'
  );
  const undefinedTests = results.filter(x => x.status === 'ERROR');

  const commentIdentiifer = `<!-- stably_${testSuiteId} -->`;
  const suiteRunDashboardUrl = getSuiteRunDashboardUrl({
    projectId,
    testSuiteRunId
  });

  // prettier-ignore
  const body = dedent`${commentIdentiifer}
  # Stably Runner - [Test Suite - '${testSuiteName}'](https://app.stably.ai/project/${projectId}/testSuite/${testSuiteId})

  Test Suite Run Result: ${
    resp.error
      ? '❌ Error - The Action ran into an error while calling the Stably backend. Please re-run'
      : failedTests.length === 0
        ? `🟢 Success (${successTests.length}/${results.length} tests passed) [[dashboard]](${suiteRunDashboardUrl})`
        : `🔴 Failure (${failedTests.length}/${results.length} tests failed) [[dashboard]](${suiteRunDashboardUrl})`
  }


  ${
    failedTests.length > 0
      ? dedent`Failed Tests:
      ${listTestMarkDown({ testSuiteRunId, tests: failedTests, projectId })}`
      : ''
  }

  ${
    undefinedTests.length > 0
      ? dedent`Unable to run tests:
      ${listTestMarkDown({ testSuiteRunId, tests: undefinedTests, projectId })}`
      : ''
  }


  ---
  _This comment was generated from [stably-runner-action](https://github.com/marketplace/actions/stably-runner)_
`;

  // Check if existing comment exists
  const commitSha = context.payload.after || context.sha;
  const { data: comments } = context.payload.pull_request
    ? await octokit.rest.issues
        .listComments({
          ...context.repo,
          issue_number: context.payload.pull_request.number
        })
        .catch(() => {
          return { data: [] };
        })
    : commitSha
      ? await octokit.rest.repos
          .listCommentsForCommit({
            ...context.repo,
            commit_sha: context.payload.after
          })
          .catch(() => {
            return { data: [] };
          })
      : { data: [] };
  const existingCommentId = comments.find(comment =>
    comment?.body?.startsWith(commentIdentiifer)
  )?.id;

  // Create or update commit/PR comment
  try {
    if (context.payload.pull_request) {
      if (existingCommentId) {
        await octokit.rest.issues.updateComment({
          ...context.repo,
          comment_id: existingCommentId,
          body
        });
      } else {
        await octokit.rest.issues.createComment({
          ...context.repo,
          body,
          issue_number: context.payload.pull_request.number
        });
      }
    } else if (commitSha) {
      if (existingCommentId) {
        await octokit.rest.repos.updateCommitComment({
          ...context.repo,
          comment_id: existingCommentId,
          body
        });
      } else {
        await octokit.rest.repos.createCommitComment({
          ...context.repo,
          body,
          commit_sha: commitSha
        });
      }
    }
  } catch (error) {
    handleCommentError(error, 'upsertGitHubComment');
  }
}

function listTestMarkDown({
  testSuiteRunId,
  tests,
  projectId
}: {
  testSuiteRunId: string;
  tests: {
    runId: string;
    testName: string;
    testId: string;
    success?: boolean;
  }[];
  projectId: string;
}) {
  return tests
    .map(
      ({ runId, testName }) =>
        `  * [${testName}](http://app.stably.ai/project/${projectId}/history/g_${testSuiteRunId}/run/${runId})`
    )
    .join('\n');
}

